CREATE OR REPLACE FUNCTION public.modifier_mon_nom(p_nom_complet text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Utilisateur non connecté';
  end if;

  if p_nom_complet is null or length(trim(p_nom_complet)) = 0 then
    raise exception 'Le nom est obligatoire';
  end if;

  update public.profiles
  set nom_complet = trim(p_nom_complet)
  where id = auth.uid();

  if not found then
    raise exception 'Profil introuvable';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.supprimer_personnel_admin(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Utilisateur non connecté';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = auth.uid()
      and role = 'admin'
      and coalesce(active, true) = true
  ) then
    raise exception 'Action réservée à l administrateur';
  end if;

  if p_user_id = auth.uid() then
    raise exception 'Vous ne pouvez pas supprimer votre propre compte';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = p_user_id
      and role = 'personnel'
  ) then
    raise exception 'Personnel introuvable';
  end if;

  delete from auth.users
  where id = p_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.supprimer_vente(p_vente_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_product_id uuid;
    v_quantite integer;
begin
    if not exists (
        select 1
        from public.profiles
        where id = auth.uid()
        and role = 'admin'
    ) then
        raise exception 'Accès refusé : administrateur uniquement.';
    end if;

    select product_id, quantite
    into v_product_id, v_quantite
    from public.ventes
    where id = p_vente_id
    for update;

    if v_product_id is null then
        raise exception 'Vente introuvable.';
    end if;

    update public.produits
    set stock_quantite = stock_quantite + v_quantite,
        updated_at = now()
    where id = v_product_id;

    delete from public.ventes
    where id = p_vente_id;
end;
$function$

